CREATE OR REPLACE FUNCTION pos.commit_exchange(p_commit_id text, p_exchange jsonb, p_items jsonb, p_moves jsonb DEFAULT '[]'::jsonb, p_payment jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_id           text := p_exchange ->> 'id';
  v_folio        text := p_exchange ->> 'folio';
  v_origen       text := p_exchange ->> 'origen_folio';
  v_hash         text;
  v_prior        pos.exchange_commits%rowtype;
  v_expira       date;
  v_hoy          date := coalesce(nullif(left(p_exchange ->> 'fecha', 10), '')::date, current_date);
  v_shortages    jsonb;
  v_reconocido   numeric := 0;
  v_entregado    numeric := 0;
  v_diferencia   numeric := 0;
  v_no_aprov     numeric := 0;
  v_base_com     numeric := 0;
  v_rec          record;
  v_products     jsonb := '[]'::jsonb;
  v_pago_monto   numeric := 0;
  v_effect       record;
  v_sellers      jsonb := '[]'::jsonb;
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para registrar cambios' using errcode = '42501';
  end if;

  -- 1) Forma
  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(coalesce(v_id, '')), '') is null
     or nullif(trim(coalesce(v_folio, '')), '') is null
     or nullif(trim(coalesce(v_origen, '')), '') is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_typeof(coalesce(p_moves, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_seller_effects, '[]'::jsonb)) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  if exists (
    select 1 from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, sku text, talla text, qty integer)
     where coalesce(x.lado, '') not in ('devuelto', 'entregado')
        or nullif(trim(coalesce(x.sku, '')), '') is null
        or nullif(trim(coalesce(x.talla, '')), '') is null
        or nullif(trim(coalesce(x.product_id, '')), '') is null
        or coalesce(x.qty, 0) <= 0
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  -- Un cambio exige las dos mitades: sin ellas es una devolución o una venta.
  if not exists (select 1 from jsonb_to_recordset(p_items) as x(lado text) where x.lado = 'devuelto')
     or not exists (select 1 from jsonb_to_recordset(p_items) as x(lado text) where x.lado = 'entregado') then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  v_hash := md5(jsonb_build_object(
    'exchange', p_exchange, 'items', p_items, 'moves', coalesce(p_moves, '[]'::jsonb),
    'payment', coalesce(p_payment, 'null'::jsonb),
    'seller_effects', coalesce(p_seller_effects, '[]'::jsonb)
  )::text);

  perform pg_advisory_xact_lock(hashtext(p_commit_id));

  -- 2) Idempotencia
  select * into v_prior from pos.exchange_commits where commit_id = p_commit_id;
  if found then
    if v_prior.payload_hash <> v_hash or v_prior.exchange_id <> v_id or v_prior.folio <> v_folio then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch');
    end if;
    return jsonb_build_object('ok', true, 'idempotent', true,
      'exchange', (select to_jsonb(e) from pos.exchanges e where e.id = v_id));
  end if;

  -- 3) Serializa todos los documentos de la misma venta
  perform 1 from pos.sales where folio = v_origen for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'sale_not_found');
  end if;

  if exists (select 1 from pos.exchanges where id = v_id) then
    return jsonb_build_object('ok', false, 'error', 'exchange_id_conflict');
  end if;

  -- 4) Plazo de posventa (H-34). El derecho a cambiar está sujeto al plazo de la
  --    venta origen; nulo significa sin límite, igual que en devoluciones.
  select return_expires_at into v_expira from pos.sales where folio = v_origen;
  if v_expira is not null and v_hoy > v_expira then
    return jsonb_build_object('ok', false, 'error', 'exchange_window_closed',
      'expires_at', v_expira);
  end if;

  -- 5) Saldo disponible (H-35/H-37). La autoridad ya suma el suministro de
  --    cambios anteriores, así que una pieza recibida antes puede recambiarse.
  with pedido as (
    select x.sku, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items) as x(lado text, sku text, talla text, qty integer)
     where x.lado = 'devuelto'
     group by x.sku, x.talla
  ),
  saldo as (
    select b.sku, b.talla, b.disponible as qty
      from pos.sale_line_balance(v_origen, v_id) b
  )
  select jsonb_agg(jsonb_build_object(
           'sku', p.sku, 'talla', p.talla,
           'requested', p.qty, 'available', coalesce(s.qty, 0)
         ) order by p.sku, p.talla)
    into v_shortages
    from pedido p
    left join saldo s on s.sku = p.sku and s.talla is not distinct from p.talla
   where p.qty > coalesce(s.qty, 0);

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_exchange_quantity',
      'items', v_shortages);
  end if;

  -- 6) Valoración. SIEMPRE en el servidor (Contrato §3).
  select coalesce(sum(x.qty * pos.line_recognized_value(v_origen, x.sku, x.talla)), 0)
    into v_reconocido
    from jsonb_to_recordset(p_items) as x(lado text, sku text, talla text, qty integer)
   where x.lado = 'devuelto';

  select coalesce(sum(x.qty * pos.list_price(x.product_id, x.talla)), 0)
    into v_entregado
    from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, talla text, qty integer)
   where x.lado = 'entregado';

  if v_entregado >= v_reconocido then
    v_diferencia := round(v_entregado - v_reconocido, 2);
    v_no_aprov := 0;
  else
    -- El sobrante se pierde: nunca sale efectivo (Contrato §4).
    v_diferencia := 0;
    v_no_aprov := round(v_reconocido - v_entregado, 2);
  end if;
  v_base_com := v_diferencia;   -- §7: sólo el excedente genera comisión

  -- 6b) El cobro se valida ANTES de escribir nada. En 20260728005700 estas dos
  --     salidas ocurrian despues de insertar cabecera, renglones y movimientos:
  --     un `return` de plpgsql no aborta la transaccion, asi que un cobro mal
  --     formado dejaba el documento a medias. Es el defecto que H-04 existe para
  --     impedir. Ahora no se escribe una sola fila hasta que el dinero cuadra.
  if v_diferencia > 0 then
    if p_payment is null then
      return jsonb_build_object('ok', false, 'error', 'payment_required',
        'expected', v_diferencia);
    end if;
    v_pago_monto := coalesce((p_payment ->> 'monto')::numeric, 0);
    if round(v_pago_monto, 2) <> v_diferencia then
      return jsonb_build_object('ok', false, 'error', 'payment_mismatch',
        'expected', v_diferencia, 'received', v_pago_monto);
    end if;
  end if;

  -- 7) Inventario. Bloqueo estable de TODOS los productos implicados, en un solo
  --    orden, para evitar deadlocks entre cambios concurrentes.
  perform p.id from pos.products p
   where p.id in (select distinct x.product_id from jsonb_to_recordset(p_items)
                    as x(product_id text))
   order by p.id
   for update;

  -- Toda talla implicada debe existir en su producto.
  with lineas as (
    select x.product_id, x.talla from jsonb_to_recordset(p_items)
      as x(product_id text, talla text) group by x.product_id, x.talla
  )
  select jsonb_agg(jsonb_build_object('product_id', l.product_id, 'talla', l.talla,
           'reason', case when p.id is null then 'product_not_found' else 'size_not_found' end)
         order by l.product_id, l.talla)
    into v_shortages
    from lineas l
    left join pos.products p on p.id = l.product_id and p.deleted_at is null
   where p.id is null
      or not exists (select 1 from jsonb_array_elements(p.stock) e where e ->> 'talla' = l.talla);

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_stock_target', 'items', v_shortages);
  end if;

  -- Reserva de lo ENTREGADO: se valida ANTES de escribir, dentro del mismo
  -- bloqueo, así que dos terminales no pueden entregar la última pieza (H-01).
  with pedido as (
    select x.product_id, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items)
        as x(lado text, product_id text, talla text, qty integer)
     where x.lado = 'entregado'
     group by x.product_id, x.talla
  )
  select jsonb_agg(jsonb_build_object('product_id', pe.product_id, 'talla', pe.talla,
           'requested', pe.qty, 'available', (e.value ->> 'stock')::integer)
         order by pe.product_id, pe.talla)
    into v_shortages
    from pedido pe
    join pos.products p on p.id = pe.product_id
    cross join lateral jsonb_array_elements(p.stock) e
   where e.value ->> 'talla' = pe.talla
     and (e.value ->> 'stock')::integer < pe.qty;

  if v_shortages is not null then
    return jsonb_build_object('ok', false, 'error', 'insufficient_stock', 'items', v_shortages);
  end if;

  -- Movimiento neto por (producto, talla): + lo devuelto, − lo entregado.
  for v_rec in
    with delta as (
      select x.product_id, x.talla,
             sum(case when x.lado = 'devuelto' then x.qty else -x.qty end)::integer as qty
        from jsonb_to_recordset(p_items)
          as x(lado text, product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select d.product_id, d.talla, d.qty,
           (e.value ->> 'stock')::integer as available,
           e.ordinality::integer - 1 as stock_index
      from delta d
      join pos.products p on p.id = d.product_id
      cross join lateral jsonb_array_elements(p.stock) with ordinality as e(value, ordinality)
     where e.value ->> 'talla' = d.talla and d.qty <> 0
     order by d.product_id, d.talla
  loop
    update pos.products p
       set stock = jsonb_set(p.stock, array[v_rec.stock_index::text, 'stock'],
             to_jsonb(greatest(v_rec.available + v_rec.qty, 0)), false),
           sync_base_version = p.sync_version,
           sync_device_id = 'exchange:' || p_commit_id
     where p.id = v_rec.product_id;
  end loop;

  -- 8) Documento
  insert into pos.exchanges (
    id, folio, origen_folio, fecha, usuario, vendedor_id, revisado_por,
    valor_reconocido, valor_entregado, diferencia, valor_no_aprovechado,
    base_comision, comision_monto, comision_base, comision_pct, notas
  ) values (
    v_id, v_folio, v_origen, p_exchange ->> 'fecha', p_exchange ->> 'usuario',
    p_exchange ->> 'vendedor_id', p_exchange ->> 'revisado_por',
    v_reconocido, v_entregado, v_diferencia, v_no_aprov, v_base_com,
    coalesce((p_exchange ->> 'comision_monto')::numeric, 0),
    nullif(p_exchange ->> 'comision_base', ''),
    coalesce((p_exchange ->> 'comision_pct')::numeric, 0),
    p_exchange ->> 'notas'
  );

  insert into pos.exchange_items (exchange_id, lado, product_id, sku, nombre, talla, qty, precio, motivo, condicion)
  select v_id, x.lado, x.product_id, x.sku, x.nombre, x.talla, x.qty,
         case when x.lado = 'entregado'
              then pos.list_price(x.product_id, x.talla)
              else pos.line_recognized_value(v_origen, x.sku, x.talla) end,
         x.motivo, x.condicion
    from jsonb_to_recordset(p_items)
      as x(lado text, product_id text, sku text, nombre text, talla text, qty integer,
           motivo text, condicion text);

  -- 9) Movimientos de inventario (historial de sólo lectura para el cliente)
  if jsonb_array_length(coalesce(p_moves, '[]'::jsonb)) > 0 then
    insert into pos.movements (fecha, tipo, producto, product_id, sku, talla, cant, ref)
    select x.fecha, x.tipo, x.producto, x.product_id, x.sku, x.talla, x.cant, coalesce(x.ref, v_folio)
      from jsonb_to_recordset(p_moves)
        as x(fecha timestamptz, tipo text, producto text, product_id text, sku text, talla text, cant integer, ref text);
  end if;

  -- 10) Cobro de la diferencia. Ledger único, con el folio PROPIO del cambio:
  --     usar el de la venta origen violaria §8 y ademas commit_sale borra por
  --     folio antes de reinsertar. Nunca se emite un pago negativo.
  if v_diferencia > 0 then
    insert into pos.sale_payments (id, folio, fecha, tipo, metodo, monto,
                                   efectivo, tarjeta, transferencia, otro)
    values (
      p_payment ->> 'id', v_folio, p_payment ->> 'fecha', 'cambio',
      coalesce(p_payment ->> 'metodo', 'Efectivo'), v_diferencia,
      coalesce((p_payment ->> 'efectivo')::numeric, 0),
      coalesce((p_payment ->> 'tarjeta')::numeric, 0),
      coalesce((p_payment ->> 'transferencia')::numeric, 0),
      coalesce((p_payment ->> 'otro')::numeric, 0)
    );
  end if;

  -- 10) Comision del excedente. Mismo criterio de reintento que `commit_sale`:
  -- si la version del vendedor ya avanzo UNO sobre la base leida y el valor final
  -- coincide, este efecto ya se aplico y es un reenvio de la cola; se deja como
  -- esta en vez de sumarlo dos veces.
  --
  -- Un cambio NO es un pedido: aqui no se tocan `ventas_mes` ni `ventas_num`, de
  -- modo que el conteo de ventas, el ticket promedio y las metas del equipo no se
  -- mueven. Solo el acumulado de comision.
  for v_effect in
    select *
      from jsonb_to_recordset(coalesce(p_seller_effects, '[]'::jsonb)) as x(
        id text, comision_acum_delta numeric, base_version bigint,
        after_comision_acum numeric
      )
  loop
    update pos.sellers
       set comision_acum = case
             when sync_version = coalesce(v_effect.base_version, 0) + 1
              and comision_acum = v_effect.after_comision_acum
             then comision_acum
             else greatest(0, comision_acum + coalesce(v_effect.comision_acum_delta, 0)) end,
           sync_base_version = sync_version,
           sync_device_id = 'exchange:' || p_commit_id
     where id = v_effect.id and active = true and deleted_at is null;
    if not found then
      raise exception 'Vendedor del cambio no existe o esta inactivo' using errcode = 'P0001';
    end if;
  end loop;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(coalesce(p_seller_effects, '[]'::jsonb))
       as x(id text, comision_acum_delta numeric)
   );

  insert into pos.exchange_commits (commit_id, exchange_id, folio, payload_hash, actor_email)
  values (p_commit_id, v_id, v_folio, v_hash, auth.jwt() ->> 'email');

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into v_products
    from pos.products p
   where p.id in (select distinct x.product_id from jsonb_to_recordset(p_items)
                    as x(product_id text));

  return jsonb_build_object(
    'ok', true, 'idempotent', false,
    'exchange', (select to_jsonb(e) from pos.exchanges e where e.id = v_id),
    'products', v_products, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.commit_return(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_stock_lines jsonb, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_return_id text := p_return ->> 'id';
  v_folio text := p_return ->> 'folio';
  v_payload_hash text;
  v_prior pos.return_commits%rowtype;
  v_sale_state text;
  v_products jsonb := '[]'::jsonb;
  v_clients jsonb := '[]'::jsonb;
  v_sellers jsonb := '[]'::jsonb;
  v_shortages jsonb;
  v_rec record;
  v_stock_row jsonb;
  v_client_id text;
  v_client_base bigint;
  v_client_delta numeric;
  v_client_after numeric;
  v_effect record;
begin
  if not (pos.is_active_admin() or pos.is_active_seller()) then
    raise exception 'Cuenta sin permiso para registrar devoluciones'
      using errcode = '42501';
  end if;

  if nullif(trim(p_commit_id), '') is null
     or nullif(trim(v_return_id), '') is null
     or nullif(trim(v_folio), '') is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_typeof(p_moves) <> 'array'
     or jsonb_typeof(p_stock_lines) <> 'array'
     or jsonb_typeof(p_seller_effects) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  if exists (
    select 1
      from jsonb_to_recordset(p_items)
        as x(return_id text, product_id text, sku text, talla text, qty integer)
     where x.return_id is distinct from v_return_id
        or nullif(trim(x.sku), '') is null
        or nullif(trim(x.talla), '') is null
        or x.qty is null
        or x.qty <= 0
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_items');
  end if;

  v_payload_hash := md5(jsonb_build_object(
    'return', p_return, 'items', p_items, 'moves', p_moves,
    'stock_lines', p_stock_lines, 'client_effect', p_client_effect,
    'seller_effects', p_seller_effects, 'legacy', coalesce(p_legacy, false)
  )::text);

  perform pg_advisory_xact_lock(hashtext(p_commit_id));

  select * into v_prior
    from pos.return_commits
   where commit_id = p_commit_id;

  if found then
    if v_prior.payload_hash <> v_payload_hash
       or v_prior.return_id <> v_return_id
       or v_prior.folio <> v_folio then
      return jsonb_build_object('ok', false, 'error', 'commit_mismatch');
    end if;
    select estado into v_sale_state from pos.sales where folio = v_folio;
    select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
      into v_products from pos.products p
     where p.id in (
       select x.product_id from jsonb_to_recordset(p_stock_lines)
         as x(product_id text, talla text, qty integer)
     );
    if p_client_effect is not null then
      select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
        into v_clients from pos.clients c
       where c.id = p_client_effect ->> 'id';
    end if;
    select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
      into v_sellers from pos.sellers s
     where s.id in (
       select x.id from jsonb_to_recordset(p_seller_effects)
         as x(id text, ventas_mes_delta numeric, comision_acum_delta numeric)
     );
    return jsonb_build_object(
      'ok', true, 'idempotent', true, 'sale_state', v_sale_state,
      'products', v_products, 'clients', v_clients, 'sellers', v_sellers
    );
  end if;

  -- Serializa todas las devoluciones del mismo folio.
  perform 1 from pos.sales where folio = v_folio for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'sale_not_found');
  end if;

  if exists (select 1 from pos.returns where id = v_return_id)
     and not coalesce(p_legacy, false) then
    return jsonb_build_object('ok', false, 'error', 'return_id_conflict');
  end if;

  -- H-35: la autoridad de cantidades es pos.sale_line_balance(), que suma
  -- TODAS las fuentes de consumo de la venta —devoluciones hoy, cambios cuando
  -- existan— y excluye esta misma devolución para permitir su reescritura.
  -- Antes de H-35 esta consulta agrupaba pos.return_items en línea, por lo que
  -- ninguna otra clase de documento podía participar del saldo.
  with requested as (
    select x.sku, x.talla, sum(x.qty)::integer as qty
      from jsonb_to_recordset(p_items)
        as x(return_id text, product_id text, sku text, talla text, qty integer)
     group by x.sku, x.talla
  ),
  disponible as (
    select b.sku, b.talla, b.disponible as qty
      from pos.sale_line_balance(v_folio, v_return_id) b
  )
  select jsonb_agg(jsonb_build_object(
           'sku', q.sku, 'talla', q.talla, 'requested', q.qty,
           'available', coalesce(d.qty, 0)
         ) order by q.sku, q.talla)
    into v_shortages
    from requested q
    left join disponible d using (sku, talla)
   where q.qty > coalesce(d.qty, 0);


  if v_shortages is not null then
    return jsonb_build_object(
      'ok', false, 'error', 'invalid_return_quantity',
      'items', v_shortages
    );
  end if;

  if coalesce((p_return ->> 'total')::numeric, 0)
     + coalesce((
       select sum(total) from pos.returns
        where folio = v_folio and id <> v_return_id
     ), 0)
     > coalesce((select total from pos.sales where folio = v_folio), 0) + 0.01 then
    return jsonb_build_object('ok', false, 'error', 'refund_exceeds_sale');
  end if;

  if not coalesce(p_legacy, false) then
    if jsonb_array_length(p_stock_lines) = 0
       or (select coalesce(sum(x.qty), 0) from jsonb_to_recordset(p_stock_lines)
             as x(product_id text, talla text, qty integer))
          <> (select coalesce(sum(x.qty), 0) from jsonb_to_recordset(p_items)
                as x(return_id text, product_id text, sku text, talla text, qty integer)) then
      return jsonb_build_object('ok', false, 'error', 'invalid_stock_lines');
    end if;

    perform p.id
      from pos.products p
     where p.id in (
       select distinct x.product_id
         from jsonb_to_recordset(p_stock_lines)
           as x(product_id text, talla text, qty integer)
     )
     order by p.id
     for update;

    with lines as (
      select x.product_id, x.talla, sum(x.qty)::integer as qty
        from jsonb_to_recordset(p_stock_lines)
          as x(product_id text, talla text, qty integer)
       group by x.product_id, x.talla
    )
    select jsonb_agg(jsonb_build_object(
             'product_id', l.product_id, 'talla', l.talla,
             'reason', case when p.id is null then 'product_not_found'
                            else 'size_not_found' end
           ) order by l.product_id, l.talla)
      into v_shortages
      from lines l
      left join pos.products p
        on p.id = l.product_id and p.deleted_at is null
     where p.id is null
        or not exists (
          select 1 from jsonb_array_elements(p.stock) e
           where e ->> 'talla' = l.talla
        );

    if v_shortages is not null then
      return jsonb_build_object(
        'ok', false, 'error', 'invalid_stock_target', 'items', v_shortages
      );
    end if;

    for v_rec in
      with lines as (
        select x.product_id, x.talla, sum(x.qty)::integer as qty
          from jsonb_to_recordset(p_stock_lines)
            as x(product_id text, talla text, qty integer)
         group by x.product_id, x.talla
      )
      select l.product_id, l.talla, l.qty,
             (e.value ->> 'stock')::integer as available,
             e.ordinality::integer - 1 as stock_index
        from lines l
        join pos.products p on p.id = l.product_id
        cross join lateral jsonb_array_elements(p.stock)
          with ordinality as e(value, ordinality)
       where e.value ->> 'talla' = l.talla
       order by l.product_id, l.talla
    loop
      update pos.products p
         set stock = jsonb_set(
               p.stock, array[v_rec.stock_index::text, 'stock'],
               to_jsonb(v_rec.available + v_rec.qty), false
             ),
             sync_base_version = p.sync_version,
             sync_device_id = 'return:' || p_commit_id
       where p.id = v_rec.product_id
       returning to_jsonb(p.*) into v_stock_row;
    end loop;
  end if;

  insert into pos.returns (
    id, folio, cliente, vendedores, metodo, total, notas, fecha
  ) values (
    v_return_id, v_folio, p_return ->> 'cliente',
    coalesce(p_return -> 'vendedores', '[]'::jsonb),
    p_return ->> 'metodo', coalesce((p_return ->> 'total')::numeric, 0),
    p_return ->> 'notas', p_return ->> 'fecha'
  )
  on conflict (id) do update set
    folio = excluded.folio,
    cliente = excluded.cliente,
    vendedores = excluded.vendedores,
    metodo = excluded.metodo,
    total = excluded.total,
    notas = excluded.notas,
    fecha = excluded.fecha,
    updated_at = now();

  delete from pos.return_items where return_id = v_return_id;
  insert into pos.return_items (
    return_id, product_id, sku, nombre, talla, qty, motivo, precio
  )
  select v_return_id, x.product_id, x.sku, x.nombre, x.talla,
         x.qty, x.motivo, x.precio
    from jsonb_to_recordset(p_items) as x(
      return_id text, product_id text, sku text, nombre text, talla text,
      qty integer, motivo text, precio numeric
    );

  if coalesce(p_legacy, false) then
    delete from pos.movements where ref = v_folio and tipo = 'Devolución';
  else
    delete from pos.movements where return_id = v_return_id;
  end if;
  insert into pos.movements (
    return_id, fecha, tipo, producto, product_id, sku, talla, cant, ref
  )
  select case when coalesce(p_legacy, false) then null else v_return_id end,
         x.fecha::timestamptz, 'Devolución', x.producto, x.product_id, x.sku, x.talla, x.cant, v_folio
    from jsonb_to_recordset(p_moves)
      as x(return_id text, fecha text, tipo text, producto text, product_id text, sku text, talla text, cant integer, ref text);

  -- H-35: el estado también sale de la autoridad única. Equivale al cálculo
  -- anterior: disponible = greatest(vendida - consumida, 0) y toda fila del
  -- balance tiene vendida > 0, así que "queda algo por consumir" es idéntico a
  -- "existe un renglón vendido con menos consumo que unidades".
  select case when exists (
    select 1 from pos.sale_line_balance(v_folio) b where b.disponible > 0
  ) then 'Devolución parcial' else 'Devuelto' end
    into v_sale_state;

  update pos.sales
     set estado = v_sale_state, updated_at = now()
   where folio = v_folio;

  if not coalesce(p_legacy, false) and p_client_effect is not null then
    v_client_id := p_client_effect ->> 'id';
    v_client_base := coalesce((p_client_effect ->> 'base_version')::bigint, 0);
    v_client_delta := coalesce((p_client_effect ->> 'total_delta')::numeric, 0);
    v_client_after := (p_client_effect ->> 'after_total')::numeric;
    update pos.clients
       set total = case
             when sync_version = v_client_base + 1 and total = v_client_after
             then total else greatest(0, total + v_client_delta) end,
           sync_base_version = sync_version,
           sync_device_id = 'return:' || p_commit_id
     where id = v_client_id and deleted_at is null;
    if not found then
      raise exception 'Cliente de la devolución no existe'
        using errcode = 'P0001';
    end if;
  end if;

  if not coalesce(p_legacy, false) then
    for v_effect in
      select * from jsonb_to_recordset(p_seller_effects) as x(
        id text, base_version bigint, ventas_mes_delta numeric,
        comision_acum_delta numeric, after_ventas_mes numeric,
        after_comision_acum numeric
      )
    loop
      update pos.sellers
         set ventas_mes = case
               when sync_version = coalesce(v_effect.base_version, 0) + 1
                and ventas_mes = v_effect.after_ventas_mes
                and comision_acum = v_effect.after_comision_acum
               then ventas_mes else greatest(0, ventas_mes + coalesce(v_effect.ventas_mes_delta, 0)) end,
             comision_acum = case
               when sync_version = coalesce(v_effect.base_version, 0) + 1
                and ventas_mes = v_effect.after_ventas_mes
                and comision_acum = v_effect.after_comision_acum
               then comision_acum else greatest(0, comision_acum + coalesce(v_effect.comision_acum_delta, 0)) end,
             sync_base_version = sync_version,
             sync_device_id = 'return:' || p_commit_id
       where id = v_effect.id and active = true and deleted_at is null;
      if not found then
        raise exception 'Vendedor de la devolución no existe o está inactivo'
          using errcode = 'P0001';
      end if;
    end loop;
  end if;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.id), '[]'::jsonb)
    into v_products from pos.products p
   where p.id in (
     select x.product_id from jsonb_to_recordset(p_stock_lines)
       as x(product_id text, talla text, qty integer)
   );
  if p_client_effect is not null then
    select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
      into v_clients from pos.clients c
     where c.id = p_client_effect ->> 'id';
  end if;
  select coalesce(jsonb_agg(to_jsonb(s) order by s.id), '[]'::jsonb)
    into v_sellers from pos.sellers s
   where s.id in (
     select x.id from jsonb_to_recordset(p_seller_effects)
       as x(id text, ventas_mes_delta numeric, comision_acum_delta numeric)
   );

  insert into pos.return_commits (
    commit_id, return_id, folio, payload_hash, actor_email
  ) values (
    p_commit_id, v_return_id, v_folio, v_payload_hash, auth.jwt() ->> 'email'
  );

  return jsonb_build_object(
    'ok', true, 'idempotent', false, 'sale_state', v_sale_state,
    'products', v_products, 'clients', v_clients, 'sellers', v_sellers
  );
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_operational_items(p_items jsonb, p_exchange boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare v_result jsonb;
begin
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then raise exception 'INVALID_REFERENCE_ITEMS'; end if;
  if exists(
    select 1 from jsonb_array_elements(p_items)i join pos.products p on p.id=i->>'product_id'
    where p.record_model='v1' and p_exchange and coalesce(i->>'lado','')<>'devuelto'
  ) then raise exception 'V1_OPERATIONAL_FORBIDDEN'; end if;
  if exists(
    select 1 from jsonb_array_elements(p_items)i join pos.products p on p.id=i->>'product_id'
    left join pos.inventory_v1_v2_map m on m.source_v1_product_id=p.id
      and m.raw_size_value=i->>'talla'
      and (m.size_scale=coalesce(i->>'size_scale',m.size_scale))
    where p.record_model='v1' and m.target_v2_product_id is null
  ) then raise exception 'HISTORICAL_REFERENCE_MAP_MISSING'; end if;
  select coalesce(jsonb_agg(
    case when p.record_model='v1' then i||jsonb_build_object(
      'source_product_id',p.id,'product_id',m.target_v2_product_id,
      'barcode_code',target.barcode_code,'size_scale',m.size_scale)
    else i end order by ordinality),'[]'::jsonb) into v_result
  from jsonb_array_elements(p_items) with ordinality x(i,ordinality)
  left join pos.products p on p.id=i->>'product_id'
  left join pos.inventory_v1_v2_map m on m.source_v1_product_id=p.id and m.raw_size_value=i->>'talla'
  left join pos.products target on target.id=m.target_v2_product_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h83_commit_exchange_delegate(p_commit_id text, p_exchange jsonb, p_items jsonb, p_moves jsonb DEFAULT '[]'::jsonb, p_payment jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  perform pos.require_current_capability('sales.exchange');
  v_result := pos.commit_exchange(
    p_commit_id, p_exchange, p_items, p_moves, p_payment, p_seller_effects
  );
  -- H-69: `comision_pct` y `comision_monto` ya los escribe `commit_exchange`.
  -- Aqui se anade lo que faltaba para reconstruir la cifra: sobre que importe se
  -- calculo y bajo que politica. Se hace en el wrapper para no retipear la
  -- funcion grande (AP-05).
  if coalesce((v_result ->> 'ok')::boolean, false) then
    perform pos.record_exchange_commission_policy(p_exchange);
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h83_commit_return_delegate(p_commit_id text, p_return jsonb, p_items jsonb, p_moves jsonb, p_stock_lines jsonb, p_client_effect jsonb DEFAULT NULL::jsonb, p_seller_effects jsonb DEFAULT '[]'::jsonb, p_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  perform pos.require_current_capability('sales.refund');
  return pos.commit_return(
    p_commit_id, p_return, p_items, p_moves, p_stock_lines,
    p_client_effect, p_seller_effects, p_legacy
  );
end;
$function$

